-- Every built-in block face and every built-in item now ships real pixel art
-- instead of falling back to the registry colour.
--
-- The bytes follow the same convention as anything uploaded through the Studio:
-- a 16x16 PNG for a block face in `blocks.texture`, a 32x32 PNG for an item in
-- `items.icon`, stored as a base64 `data:image/png` URL (the client and the
-- upload validator both match that exact shape). The `colour` column stays: the
-- renderer only compiles textures in "detailed" mode, so flat mode and any
-- client that cannot decode the image still paints with the registry colour.
--
-- Glass is painted as a pale window rather than drawn with real transparency,
-- because the voxel material this engine builds is opaque.

-- A beacon face is a cut crystal: the registered colour is pale ice, so the
-- bright rhombus is the light it carries.

-- Block faces (16x16)
UPDATE blocks SET texture = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAjElEQVR42pWTMQqAMAxF/ykd3MTBzdXBzWM4OXrLSgqBEJL8OoTS2jwfP4rjvJrU/bx9Xbe96VlU/jnYpWle0uYUoEZqZSHeuATYvYeEANvkAZkJWIjMBCw8ZpJmEOlGhUr3F2CkOboDPZS1mnf2AlQfi59OOUaFaI38B3QKDJgCqiyGAD5Q2Yt+lMMHCwNyisAKvg4AAAAASUVORK5CYII=' WHERE id = 'builtin:stone';
